import sys
from playwright.sync_api import sync_playwright
STUB=open('/home/claude/work/tests-front/stub_recruit.js',encoding='utf8').read()
res=[]
def check(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); errs=[]
    def new(url,pre="",w=1200):
        pg=b.new_page(viewport={'width':w,'height':950},locale='fr-FR'); pg.on("pageerror",lambda e:errs.append(str(e)))
        pg.on("dialog",lambda d:d.accept()); pg.route("**/cdn.jsdelivr.net/**",lambda r:r.abort())
        pg.add_init_script(pre+STUB); pg.goto("http://localhost:8765/"+url); pg.wait_for_timeout(1000); return pg
    # ----- candidat
    c=new("carrieres.html")
    check("offres : seule l'offre ouverte affichée, HTML échappé", "Développeur backend" in c.inner_text("#offers") and "Poste fermé" not in c.inner_text("#offers") and c.locator("#offers i").count()==0)
    check("offres : missions et compétences listées", "Concevoir des API" in c.inner_text("#offers") and "Postgres" in c.inner_text("#offers"))
    check("formulaire : offre ajoutée à la liste", c.locator("#of option").count()==2)
    c.click('[data-apply="o1"]'); c.wait_for_timeout(200)
    check("« Postuler » pré-sélectionne le poste", c.input_value("#of")=="o1")
    check("suivi : candidature a1 avec statut et historique", "APP-AAAA111111" in c.inner_text("#mine-list") and "Informations demandées" in c.inner_text("#mine-list") and "portfolio" in c.inner_text("#mine-list"))
    check("suivi : la note interne n'est pas visible du candidat", "Note secrète" not in c.inner_text("#mine-list"))
    check("suivi : candidature des autres invisible", "APP-BBBB222222" not in c.inner_text("#mine-list"))
    c.fill("#r-a1","Voici mon portfolio : https://exemple.dev"); c.click('[data-reply="a1"] button'); c.wait_for_timeout(500)
    check("réponse du candidat : statut repasse en examen", c.evaluate("window.__db.recruitment_applications.find(a=>a.id==='a1').status")=="in_review" and "Examen" in c.inner_text("#mine-list").title() or "examen" in c.inner_text("#mine-list").lower())
    c.click("#go"); c.wait_for_timeout(300)
    check("envoi vide : erreurs de champs, aucun envoi", "nom" in c.inner_text("#en").lower() and c.evaluate("window.__db.recruitment_applications.length")==2)
    c.fill("#n","Moussa Traoré"); c.fill("#m","moussa@test.io"); c.fill("#msg","Court"); c.check("#ok"); c.click("#go"); c.wait_for_timeout(300)
    check("message trop court refusé", "20" in c.inner_text("#emsg"))
    c.fill("#msg","Développeur Node avec cinq ans d'expérience sur Postgres."); c.set_input_files("#cv",{"name":"cv.exe","mimeType":"application/octet-stream","buffer":b"x"}); c.click("#go"); c.wait_for_timeout(300)
    check("CV au mauvais format refusé", "Format" in c.inner_text("#ec") and c.evaluate("window.__uploads.length")==0)
    c.set_input_files("#cv",{"name":"mon cv é.pdf","mimeType":"application/pdf","buffer":b"%PDF-1.4"}); c.click("#go"); c.wait_for_timeout(600)
    check("envoi : CV déposé dans le dossier du candidat, nom assaini", c.evaluate("window.__uploads.length")==1 and c.evaluate("window.__uploads[0]").startswith("u1/") and " " not in c.evaluate("window.__uploads[0]"))
    check("envoi : référence affichée", "APP-NEW" in c.inner_text("#ap"))
    check("envoi : e-mail d'alerte existant (notify-application) conservé", c.evaluate("window.__emails")==1)
    check("suivi : nouvelle candidature visible", c.locator("#mine-list article").count()==2)
    f=new("carrieres.html","window.__failInsert='too_many_open_applications';")
    f.fill("#n","Awa K"); f.fill("#m","a@b.co"); f.fill("#msg","Un message suffisamment long pour passer."); f.check("#ok"); f.set_input_files("#cv",{"name":"cv.pdf","mimeType":"application/pdf","buffer":b"%PDF"}); f.click("#go"); f.wait_for_timeout(500)
    check("limite de 3 candidatures : message clair et CV retiré", "3 candidatures" in f.inner_text("#ap") and f.evaluate("window.__removed")!=None)
    a=new("carrieres.html","window.__ANON=true;")
    check("visiteur : offres visibles, invitation à se connecter, envoi refusé", a.locator("#offers article").count()==1 and a.is_visible("#need-login"))
    a.fill("#n","Visiteur X"); a.fill("#m","v@x.co"); a.fill("#msg","Un message suffisamment long pour passer."); a.check("#ok"); a.click("#go"); a.wait_for_timeout(300)
    check("visiteur : aucune candidature créée", "Connectez-vous" in a.inner_text("#ap") and a.evaluate("window.__db.recruitment_applications.length")==2)
    # ----- administrateur
    ad=new("admin.html","window.__ADMIN=true;")
    check("admin : tableau des 2 candidatures", ad.locator("#t-apps tbody tr").count()==2)
    ad.click('[data-open="a1"]'); ad.wait_for_timeout(500)
    check("admin : détail avec message échappé et historique complet (note interne incluse)", ad.locator("#d-msg b").count()==0 and "Note secrète" in ad.inner_text("#d-events") and ad.is_visible("#d-cv"))
    check("admin : actions autorisées depuis « Informations demandées »", ad.locator("#d-actions button").count()==2)
    ad.click('[data-open="a2"]'); ad.wait_for_timeout(300); ad.click('[data-to="in_review"]'); ad.wait_for_timeout(400)
    check("admin : passage en examen enregistré", ad.evaluate("window.__db.recruitment_applications.find(a=>a.id==='a2').status")=="in_review")
    ad.click('[data-to="info_requested"]'); ad.wait_for_timeout(300)
    check("admin : demande d'informations sans message refusée", "obligatoire" in ad.inner_text("#d-err") and ad.evaluate("window.__db.recruitment_applications.find(a=>a.id==='a2').status")=="in_review")
    ad.fill("#d-note","Merci de préciser vos références."); ad.click('[data-to="info_requested"]'); ad.wait_for_timeout(500)
    check("admin : demande d'informations envoyée au candidat", ad.evaluate("window.__db.recruitment_events.some(e=>e.application_id==='a2'&&e.status_to==='info_requested'&&e.body.includes('références'))"))
    ad.click('[data-to="in_review"]'); ad.wait_for_timeout(300); ad.click('[data-to="interview"]'); ad.wait_for_timeout(300); ad.click('[data-to="accepted"]'); ad.wait_for_timeout(500)
    check("admin : acceptation (après confirmation) => statut retenu, badge déclenché côté serveur", ad.evaluate("window.__db.recruitment_applications.find(a=>a.id==='a2').status")=="accepted" and ad.evaluate("window.__badge")=="u9")
    check("admin : décision finale, plus d'action possible", ad.locator("#d-actions button").count()==0)
    ad.fill("#d-comment","Très bon profil"); ad.click("#d-comment-go"); ad.wait_for_timeout(400)
    check("admin : note interne ajoutée", ad.evaluate("window.__db.recruitment_events.some(e=>e.kind==='internal_comment'&&e.body==='Très bon profil'&&!e.visible_to_candidate)"))
    ad.click('[data-open="a1"]'); ad.wait_for_timeout(300); ad.click("#d-cv"); 
    ad.click("#s-offers"); ad.fill("#o-title","Designer produit"); ad.fill("#o-resp","Maquettes\nSystème de design"); ad.click('#o-form button[type=submit]'); ad.wait_for_timeout(500)
    check("admin : offre publiée et listée", ad.evaluate("window.__db.job_offers.some(o=>o.title==='Designer produit'&&o.status==='open'&&o.responsibilities.length===2)") and "Designer produit" in ad.inner_text("#t-offers"))
    ad.click('[data-toggle="o1"]'); ad.wait_for_timeout(400)
    check("admin : fermeture d'une offre", ad.evaluate("window.__db.job_offers.find(o=>o.id==='o1').status")=="closed")
    nm=new("admin.html")
    check("non-admin : accès refusé, aucune donnée", "refusé" in nm.inner_text("#state").lower() and nm.is_hidden("#panel"))
    mb=new("carrieres.html","",390)
    check("mobile : pas de défilement horizontal", mb.evaluate("document.documentElement.scrollWidth<=window.innerWidth+1"))
    print("ERREURS:",sorted(set(errs)))
    check("aucune erreur JS propre (hors CDN)", not [x for x in errs if 'gsap' not in x.lower() and 'ScrollTrigger' not in x])
    b.close()
print(f"{sum(res)}/{len(res)} OK"); sys.exit(0 if all(res) else 1)
